INSERT INTO public.service_catalog_versions(service_code,version,snapshot,contract_master_version,created_by) SELECT code,version,to_jsonb(s),last_contract_master_version,null FROM public.service_catalog s WHERE code IN ('a','aa','ab','ac','ad','ae','af','ag','ah','ai','aj','ak','al','am','an','ao','b','c','d','e','f','g','h','i','j','k','l','m','n','o','p','q','r','s','t','u','v','w','x','y','z') ON CONFLICT(service_code,version) DO NOTHING;

